fn equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since the problem guarantees `a` and `b` have the same length,
    // we can either assert that to catch misuse in debug builds
    // or just zip them directly.
    assert_eq!(a.len(), b.len(), "`a` and `b` must have the same length");

    // Zip the two vectors, compare element-wise, and collect into a Vec<bool>.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x == y)
     .collect()
}

